const KIND: Record<string, string> = { bikes: 'electric bike', scooters: 'electric scooter', helmets: 'bicycle helmet', gloves: 'pair of cycling gloves', locks: 'bike lock', lights: 'bike light' };

export const FEED_PRODUCTS: Product[] = ROWS.map((r) => {
  const isBike = r.group === 'bikes';
  const facts = ['Brand: ' + r.brand, ...(r.wh ? [r.wh + ' Wh battery'] : []), ...(r.motor ? [r.motor + ' drive'] : []), ...(r.nm ? [r.nm + ' Nm torque'] : [])];
  return {
    id: 'feed-' + r.slug,
    name: r.name,
    slug: r.slug,
    subtitle: r.brand + ' ' + KIND[r.group],
    category: r.cat,
    categoryLabel: r.label,
    subcategory: r.subLabel,
    subcategoryId: r.subId,
    brand: r.brand,
    focusKeyword: r.name.toLowerCase().replace(/["']/g, ''),
    price: r.price,
    compareAtPrice: r.rrp || undefined,
    rating: 0,
    reviewsCount: 0,
    image: '',
    hoverImage: '',
    gallery: [],
    inStock: true,
    stockCount: 0,
    motor: r.motor ? r.motor + ' motor' : '',
    motorType: 'Mid-Drive',
    torqueNm: r.nm,
    batteryWh: r.wh,
    batterySpec: r.wh ? r.wh + ' Wh battery' : '',
    rangeKm: 0,
    topSpeedKmH: isBike ? 25 : 0,
    frameType: r.frame,
    weightKg: 0,
    payloadKg: 0,
    brakes: isBike ? 'See spec sheet' : '',
    gears: isBike ? 'See spec sheet' : '',
    auCompliance: isBike ? 'EN15194 pedal-assist, 25 km/h assist limit' : '',
    description: 'The ' + r.name + ' is a ' + KIND[r.group] + ' from ' + r.brand + '. Check the spec sheet for full details, and ask us to confirm size, colour and availability before you order.',
    shortDescription: r.brand + ' ' + KIND[r.group] + '.',
    features: facts,
    tags: [],
    sizeVariants: [{ id: 'standard', label: 'Standard (confirm size when ordering)', priceDelta: 0 }],
    recommendedAddOns: [],
  };
});
